def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)
    tests = [fmt(['push 1', 'peek']), fmt(['pop']), fmt(['push 0', 'pop', 'pop', 'peek']),
             fmt(['push -5', 'push 5', 'peek', 'pop', 'peek', 'pop', 'peek']), fmt(['peek']),
             fmt(['push 1000000000', 'push -1000000000', 'pop', 'pop'])]
    for n in (3, 5, 8, 12, 16, 25):
        for _ in range(3):
            ops = []
            for _ in range(n):
                r = rng.random()
                if r < 0.45:
                    ops.append('push %d' % rng.randint(-20, 20))
                elif r < 0.75:
                    ops.append('pop')
                else:
                    ops.append('peek')
            ops.append('pop')
            tests.append(fmt(ops))
    N = 100000
    ops = ['push %d' % rng.randint(-10**9, 10**9) for _ in range(N // 2)] + ['pop'] * (N // 2)
    tests.append(fmt(ops))
    ops = []
    for _ in range(N):
        r = rng.random()
        if r < 0.6:
            ops.append('push %d' % rng.randint(-10**9, 10**9))
        elif r < 0.8:
            ops.append('pop')
        else:
            ops.append('peek')
    tests.append(fmt(ops))
    ops = ['push %d' % rng.randint(-10**9, 10**9) for _ in range(N // 2)]
    for _ in range(N // 2):
        ops.append('peek' if rng.random() < 0.5 else 'push 7')
    tests.append(fmt(ops))
    ops = []
    while len(ops) < N - 2:
        ops += ['push %d' % rng.randint(1, 10**9), 'peek', 'pop']
    ops = ops[:N]
    tests.append(fmt(ops))
    return tests
